function renderInfo(n){const paragraph=(n.c||[]).find(x=>x.name==='Paragraph');let main=paragraph?.c||n.c||[];if(main.length===1&&main[0].name==='Frame 55')main=main[0].c||[];const flight=main.some(x=>'t'in x&&/航空/.test(x.t))||(main.length>=3&&main.some(x=>'t'in x&&/\d[:：]\d/.test(x.t))&&main.some(x=>'t'in x&&/[¥￥€]/.test(x.t)));const cell=t=>`<span class="${/[¥￥€]/.test(t)?'price':/\d[:：]\d|分钟|营业|全程/.test(t)?'schedule':''}">${placeText(t).replace(/\n/g,'<br>')}</span>`;const row=main.map((x,i)=>{if('t'in x)return `<span class="info-cell ${/[¥￥€]/.test(x.t)?'price':i===0?'info-label':flight||/\d[:：]\d|分钟|全程|营业/.test(x.t)?'schedule':''}">${placeText(x.t)}</span>`;return `<span class="info-end">${allText(x).map(cell).join('')}</span>`;}).join('');const details=(n.c||[]).filter(x=>x!==paragraph);return `<div class="info-box ${flight?'flight-box':''}"><div class="info-row">${row}</div>${paragraph?details.map(x=>'t'in x?`<p class="info-detail">${inlineText(x.t,x.links||[])}</p>`:renderNode(x)).join(''):''}</div>`;}
function renderNode(n){if('t'in n)return renderCopy(n);const list=allText(n).filter(Boolean);if(!list.length)return '';if(/拍照点/.test(n.name))return `<div class="photo-note"><span class="note-label">📸 拍照点</span><span>${placeText(list.filter(t=>!['📸','拍照点'].includes(t)).join(' '))}</span></div>`;if(/交通胶囊|时长胶囊|活动时长标签|chip|badge/i.test(n.name))return `<div class="pill-box">${list.map(t=>`<p class="copy"><span class="text-line">${esc(t).replace(/\n/g,'<br>')}</span></p>`).join('')}</div>`;if(n.name==='Background'||n.name==='价格与时长卡')return renderInfo(n);if((n.c||[]).some(x=>/交通胶囊|活动时长标签/.test(x.name||'')))return `<div class="activity-tags">${n.c.map(renderNode).join('')}</div>`;return `<div>${(n.c||[]).map(renderNode).join('')}</div>`;}
