function mediaDay(d,c,home=false){const meta=home?`<p class="overview-meta">${[d.tags.filter(t=>!t.includes('✈')).join(' · ')||'无自驾'].map(t=>`<span class="driving-text">${esc(t)}</span>`).join('')}${d.tags.filter(t=>t.includes('✈')).map(t=>`<span class="flight-text">${esc(flightLabel(d,t))}</span>`).join('')}</p>`:tagHTML(d.tags.map(t=>flightLabel(d,t)));return `<a class="media-day ${home?'home-day':!d.photos.length?'no-photos':''}" href="#day/${d.num}" style="--theme:${c.color}">${home?`<div class="side-thumb home-thumb">${dayThumbnail(d)?`<img src="${dayThumbnail(d)}" width="160" height="90" alt="" loading="lazy" decoding="async">`:''}<span>D${d.num}</span></div>`:`<span class="day-num">${String(d.num).padStart(2,'0')}</span>`}<div><h3>${esc(d.title)}</h3><p class="date">${esc(d.date)}</p>${meta}</div>${home?'':photoHTML(d.photos,true)}</a>`;}
function dayRanges(dayNumbers){const sorted=[...new Set(dayNumbers)].sort((a,b)=>a-b),groups=[];for(const day of sorted){const last=groups.at(-1);if(last&&day===last[1]+1)last[1]=day;else groups.push([day,day]);}return groups.map(([first,last])=>first===last?`D${first}`:`D${first}–D${last}`).join(' · ');}
function cityMapLabel(p){return p.core?`<span class="city-label-name">${esc(p.name)}</span><span class="city-label-days">${esc(dayRanges(p.days))}</span>`:esc(p.name);}
const cityProfiles={"p24": {"intro": "特罗姆瑟把北极户外体验与城市生活连在一起：白天可以前往周边岛屿和峡湾，返回后仍能在港口、博物馆、餐厅与咖啡馆里放松。", "plan": "D2（2月7日）鲸岛自驾与缆车；D3上午自主滑雪、下午驯鹿；D4峡湾游船与海钓后去塞尼亚；D8返回，D9飞冰岛。", "highlights": ["鲸岛Kvaløya：Ersfjordbotn峡湾短途自驾。", "海上峡湾游船、驯鹿雪橇或越野滑雪入门。", "城市散步：极地博物馆、Storgata与港口。"], "source": "https://www.visittromso.no/winter"}, "p30": {"intro": "塞尼亚常被称为“微缩挪威”：陡峭山体、峡湾、白沙海滩与渔业村落交替出现，风景主要沿海岸公路展开，适合边开边停。", "plan": "D4晚上抵达并连住北部两晚；D5（2月10日）Hesten徒步看Segla，D6上午海岸短停后直接赴罗弗敦南部Fredvang。", "highlights": ["Hesten：冬季向导带队，从观景路线欣赏Segla。", "Ersfjordstranda：海滩与环抱海湾的山体。", "Tungeneset、Bergsbotn：本行程中的海岸与峡湾观景停留。", "Mefjordvær一带：渔村、山海景色与住宿安排。"], "source": "https://www.visittromso.no/region/senja"}, "p40": {"intro": "罗弗敦群岛最鲜明的画面，是雪山直接落入海面，桥梁串起渔村、海湾和白沙滩。冬季的渔业生活也是旅行的一部分，港口、渔船与红色渔屋让风景更有生活感。", "plan": "D6（2月11日）塞尼亚直接到Fredvang入住；D7游览南部后住斯沃尔维尔，D8游览北部后返回特罗姆瑟。", "highlights": ["斯沃尔维尔：港口生活与渔村散步。", "亨宁斯维尔：桥梁相连的海岛渔村和港湾街道。", "Hamnøy、雷纳：红色渔屋、桥梁、雪峰与海湾。"], "source": "https://www.nasjonaleturistveger.no/en/routes/lofoten"}, "p52": {"intro": "雷克雅未克是冰岛首都，紧凑的市中心适合步行。哈尔格林姆教堂、海边的Harpa音乐厅，与街头的咖啡馆和商店形成建筑、海港与城市生活相连的游览节奏。", "plan": "D9（2月14日）14:20抵达机场，取车后16:00蓝湖，晚上进市区；D10出发南岸；D13返程，D14（2月19日）飞哥本哈根。", "highlights": ["城市地标：哈尔格林姆教堂与Harpa音乐厅。", "海滨与街头：港口方向散步、沿途咖啡与购物。", "南岸自驾：此处是出发和返程的城市枢纽。"], "source": "https://www.visiticeland.com/the-regions/reykjavik-the-capital/"}, "p58": {"intro": "维克是冰岛南岸的小型海滨村落，周边由黑沙、玄武岩、海蚀柱与山体构成强烈的地貌对比。这里也是本行程瀑布段与冰川段之间的休整点。", "plan": "D10看双瀑布后住维克，D11看黑沙滩，再经教堂镇东行至Hof。", "highlights": ["Reynisfjara：黑沙滩、玄武岩柱与离岸海蚀柱。", "镇内短走：海滨村落与周围山海景色。", "行程补给：结合原计划在镇内用餐、加油后继续东行。"], "source": "https://www.south.is/en/destinations/towns/vik"}, "p65": {"intro": "Hof村附近是本次南岸行程的冰川腹地住宿区域。与城市街区不同，这一段的重点是草皮教堂、山体、冰川地貌，以及前往冰洞和冰河湖的衔接。", "plan": "D11抵达Hof附近，D12冰川、冰河湖和钻石沙滩，D13向西返程。", "highlights": ["Hofskirkja：原行程中可顺路短停的草皮教堂。", "Skaftafell／Falljökull：原计划的冰川活动区域。", "Jökulsárlón与钻石沙滩：D12冰川与海岸拍摄安排。"], "source": "https://www.visiticeland.com/the-regions/the-south/"}, "p73": {"intro": "哥本哈根把港口风景、丹麦设计与城市日常放在很近的距离内。新港的彩色建筑、设计博物馆、家居店和步行街，适合在旅程最后几天放慢节奏。", "plan": "D14（2月19日）新港、王宫教堂外观与FRAMA；D15设计博物馆、Illums Bolighus、黑钻图书馆，20:00飞上海。", "highlights": ["新港、阿美琳堡宫与腓特列教堂外观。", "FRAMA、Illums Bolighus与丹麦设计博物馆。", "黑钻图书馆：临水现代建筑和公共中庭。"], "source": "https://www.visitcopenhagen.com/copenhagen/planning/inspiration/72-hours-in-copenhagen"}, "p1": {"intro": "赫尔辛基适合把公共建筑、历史街区与芬兰设计放进一条步行路线：中央车站、Oodi、岩石教堂，以及Esplanadi周边商店各有不同的建筑与生活气质。", "plan": "D1（2月6日）下午看赫尔辛基公共建筑与设计商店；D2乘07:35–08:35航班抵达特罗姆瑟。", "highlights": ["Oodi：木质曲面与公共阅读空间。", "岩石教堂：避开周日礼拜，按当周观光时间取舍。", "Esplanadi、Marimekko与Stockmann：择店逛芬兰设计。"], "source": "https://oodihelsinki.fi/en/"}};
cityProfiles["p-reystays"]={"intro": "霍芬是冰岛东南海岸的小镇，也是本次连住两晚的住宿基地。周边可看雪山、冰川与海岸，Stokksnes蝙蝠山位于镇东。", "plan": "D11抵达REY Stays；D12清晨西行到Hof参加冰洞，下午冰河湖后回住处；D13蝙蝠山后西返。", "highlights": ["REY Stays：两卧室、窗景及露台。", "冰河湖与钻石沙滩位于西侧，冰洞当天需往返。", "Stokksnes：山峰、黑沙丘和海岸摄影。"], "source": "https://www.booking.com/hotel/is/reystays-lodges.zh-cn.html"};
function coreCities(){const specs=[["p1", "赫尔辛基", "Helsinki Finland", null, [1, 2], "right", [9, 8]], ["p24", "特罗姆瑟", "Tromso Norway", null, [2, 3, 4, 8, 9], "right", [9, -24]], ["p30", "塞尼亚", "Senja Norway", null, [4, 5, 6], "left", [-9, 0]], ["p40", "罗弗敦群岛", "Lofoten Norway", null, [6, 7, 8], "left", [-9, 24]], ["p52", "雷克雅未克", "Reykjavik Iceland", null, [9, 10, 13, 14], "top", [0, -12]], ["p58", "维克", "Vik Iceland", null, [10, 11], "bottom", [0, 9]], ["p-reystays", "霍芬 Höfn", "Hofn Iceland", null, [11, 12, 13], "right", [9, 0]], ["p73", "哥本哈根", "Copenhagen Denmark", null, [14, 15], "right", [9, 0]]];return specs.map(([id,name,query,coord,ds,direction,offset])=>{const original=points.find(p=>p.id===id),profile=cityProfiles[id];return {...original,cityProfile:profile,id:'core-'+id,name,query,coord:coord||original.coord,days:ds,core:true,kind:'city',direction,offset,description:profile.intro,imageReference:true};});}

function sideRender(){const c=countryById(currentCountry);$('#side-tabs').innerHTML=countries.map(x=>`<button data-side-country="${x.id}" style="--theme:${x.color}" class="${c.id===x.id?'active':''}" aria-selected="${c.id===x.id}">${x.name}</button>`).join('');$('#side-content').innerHTML=`<a class="side-overview ${view.type==='country'?'active':''}" href="#country/${c.id}"><span class="ov-icon">↗</span><div><strong>${c.name} · 路线总览</strong><small>${c.subtitle} · ${c.days.length} 天</small></div></a><div class="side-label">DAILY ITINERARY / 每日行程</div>${c.days.map(d=>`<a href="#day/${d.num}" class="side-day ${view.num===d.num?'active':''}" style="--theme:${c.color}"><div class="side-thumb">${dayThumbnail(d)?`<img src="${dayThumbnail(d)}" width="160" height="90" alt="" loading="lazy" fetchpriority="low" decoding="async">`:''}<span>DAY ${String(d.num).padStart(2,'0')}</span></div><div><h3>${esc(d.title)}</h3><small>${esc(d.date.split(' · ')[0])}</small></div></a>`).join('')}`;document.documentElement.style.setProperty('--accent',c.color);$$('.budget-icon,.mobile-budget').forEach(el=>{el.classList.toggle('active',['budget','experience','stay'].includes(view.type));if(['budget','experience','stay'].includes(view.type))el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});}
function setCountry(id){currentCountry=id;sideRender();$$('[data-home-country]').forEach(b=>{const a=b.dataset.homeCountry===id;b.classList.toggle('active',a);b.setAttribute('aria-selected',String(a));});}
function mapMarkup(id,title,pts){return `<div class="map-block"><div class="map-canvas" id="${id}" aria-label="${esc(title)}"></div><div class="map-banner"><strong>${esc(title)}</strong><div class="map-banner-meta"><span>${pts.length} 个${pts[0]?.core?'核心城市／区域':'行程点位'} · 点击标记探索</span>${id==='country-map'?'<span class="map-route-legend">虚线：自驾／飞行／轮渡</span>':''}</div></div><button class="expand-map" data-expand="${id}" aria-label="展开地图与点位列表"><svg class="map-control-icon" viewBox="0 0 24 24" width="20" height="20" aria-hidden="true" focusable="false"><path d="M14 3h7v7M21 3l-7 7M10 21H3v-7M3 21l7-7"/></svg></button></div>`;}
function getPoints(type,id){if(type==='home')return coreCities();if(type==='country'){const c=countryById(id);return points.filter(p=>p.coord&&p.countryId===c.id&&p.days.some(n=>c.days.some(d=>d.num===n)));}const excluded={9:['p0','p20'],14:['p51']};const ordered=countryDayStops[Number(id)]||[];return points.filter(p=>p.coord&&p.days.includes(Number(id))&&!(excluded[Number(id)]||[]).includes(p.id)).sort((a,b)=>{const ai=ordered.indexOf(a.id),bi=ordered.indexOf(b.id);return (ai<0?999:ai)-(bi<0?999:bi);});}
function staySummaryTable(){const rows=[["2.6", "浦东✈️赫尔辛基", "约11h15m", ["2.6 上海 08:40 → 赫尔辛基 12:55 · 直飞 ¥6,141"]], ["2.7", "赫尔辛基✈️特罗姆瑟", "2h", ["2.7 赫尔辛基 07:35 → 特罗姆瑟 08:35 · 直飞 ¥2,265"]], ["2.7–2.14", "挪威北部", "—", []], ["2.14–2.19", "冰岛南岸", "7h30m（含转机）", ["2.14 特罗姆瑟 07:50 → 雷克雅未克 14:20 / 卑尔根中转2h50m · ¥1,487"]], ["2.19–2.20", "哥本哈根", "直飞3h15m", ["2.19 雷克雅未克 07:30 → 哥本哈根 11:45 · 直飞 ¥1,692"]], ["2.20–2.21", "哥本哈根✈️上海", "10h30m", ["2.20 哥本哈根 20:00 → 上海 次日13:30 · 直飞 ¥4,376"]]];return `<section class="stay-summary" aria-label="日期、地点与飞行时长"><div class="stay-table-scroll" role="region" aria-label="横向滚动完整行程表格" tabindex="0"><table><thead><tr><th scope="col">日期</th><th scope="col">地点</th><th scope="col"><span class="stay-flight-heading">飞行时长</span></th></tr></thead><tbody>${rows.map(([date,place,duration,details])=>`<tr class="stay-main-row"><td>${esc(date)}</td><td>${esc(place)}</td><td class="stay-flight-cell"><span>${esc(duration)}</span>${details.length?`<small class="stay-flight-options" tabindex="0" title="${esc(details.join(' / '))}">${esc(details.join(' / '))}</small>`:''}</td></tr>`).join('')}</tbody></table></div></section><p class="holiday-note">春节假期：2.5-2.13<span class="flight-local-time">航班时刻均为当地时间</span></p>`;}

function renderHome(){const pts=getPoints('home');$('#main').innerHTML=`<div class="page-wrap"><header class="home-intro"><div><span class="eyebrow">NORDIC JOURNEY / 2027 · VERSION 2</span><h1>北欧<span>旅行计划</span><small class="version-badge">V2</small></h1></div><div class="intro-meta"><strong>4 个国家 · 16 天</strong><br>2027.02.06 — 02.21</div></header>${mapMarkup('home-map','四国路线总览',pts)}<p class="version-difference">相比 V1，V2 取消罗瓦涅米，2月7日08:35抵达特罗姆瑟；增加一天塞尼亚，冰岛顺延一天，哥本哈根压缩为两天，仍2月21日抵沪。</p>${staySummaryTable()}<nav class="country-tabs" aria-label="国家电梯导航">${countries.map(c=>`<button data-home-country="${c.id}" style="--theme:${c.color}" aria-selected="false">${c.name}</button>`).join('')}</nav>${countries.map(c=>`<section class="country-card home-country-card" aria-label="${c.name}行程" id="section-${c.id}" data-country-section="${c.id}" style="--theme:${c.color}">${countryReferenceHTML(c)}${c.days.map(d=>mediaDay(d,c,true)).join('')}</section>`).join('')}</div>`;createMap('home-map',pts,'四国路线总览');setCountry(currentCountry);observer=new IntersectionObserver(entries=>{if(navLock)return;const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>a.boundingClientRect.top-b.boundingClientRect.top);if(visible[0])setCountry(visible[0].target.dataset.countrySection);},{rootMargin:'-130px 0px -55% 0px',threshold:0});$$('[data-country-section]').forEach(n=>observer.observe(n));}
function renderCountry(c){const pts=getPoints('country',c.id);$('#main').innerHTML=`<div class="page-wrap" style="--theme:${c.color}"><header class="country-cover"><span class="eyebrow">NORDIC JOURNEY / 2027 · VERSION 2</span><h1>${esc(c.cover[1])}<span>${c.subtitle}</span></h1></header>${mapMarkup('country-map',c.name+'路线总览',pts)}<section class="country-card">${countryReferenceHTML(c)}${c.days.map(d=>mediaDay(d,c,true)).join('')}</section>${c.notes.map(t=>`<p class="source-note">${esc(t)}</p>`).join('')}</div>`;createMap('country-map',pts,c.name+'路线总览',false,c.id);}
function renderDay(d,c){const pts=getPoints('day',d.num),prev=days.find(x=>x.num===d.num-1),next=days.find(x=>x.num===d.num+1);$('#main').innerHTML=`<div class="page-wrap" style="--theme:${c.color}"><nav class="breadcrumb"><a href="#home">首页</a><span>/</span><a href="#country/${c.id}">${c.name}</a><span>/ DAY ${String(d.num).padStart(2,'0')}</span></nav><article class="detail-card"><header class="day-heading"><span class="day-num">${String(d.num).padStart(2,'0')}</span><div class="heading-info"><h1>${placeText(d.title)}</h1><p>${esc(d.date)}</p>${d.tags.filter(t=>!t.includes('✈')).length?`<p class="day-drive-meta">${d.tags.filter(t=>!t.includes('✈')).map(esc).join(' · ')}</p>`:''}</div>${d.tags.some(t=>t.includes('✈'))?tagHTML(d.tags.filter(t=>t.includes('✈')).map(t=>flightLabel(d,t))):''}</header>${dayPhotos(d).length?`<div class="detail-photos">${photoHTML(dayPhotos(d),false,true)}</div>`:''}<div class="timeline">${d.activities.map(a=>`<section class="activity${a.excluded?' is-excluded':''}"><div class="activity-time"><span>${esc(a.time[0]||'')}</span><strong>${esc(a.time.slice(1).join(' · '))}</strong></div><span class="activity-emoji">${esc(a.emoji)}</span><div class="activity-content"><h2>${placeText(a.title)}</h2>${a.body.map(renderNode).join('')}</div></section>`).join('')}</div>${dailyStayHTML(d)}</article><section class="map-section"><div class="map-heading"><h2 class="section-heading">当日地图</h2><small>${pts.length} 个点位 · 可缩放与展开</small></div>${mapMarkup('day-map',`DAY ${String(d.num).padStart(2,'0')} · 沿途点位`,pts)}</section><nav class="day-pagination">${prev?`<a href="#day/${prev.num}"><small>← 上一天 · DAY ${String(prev.num).padStart(2,'0')}</small>${esc(prev.title)}</a>`:'<span></span>'}${next?`<a href="#day/${next.num}"><small>下一天 · DAY ${String(next.num).padStart(2,'0')} →</small>${esc(next.title)}</a>`:''}</nav></div>`;createMap('day-map',pts,`DAY ${String(d.num).padStart(2,'0')} · 当日地图`,false,null,d.num);}
const budget={"people": 2, "nights": 14, "nightly": 1000, "visa": 1000, "flights": [["上海 → 赫尔辛基", 6141], ["赫尔辛基 → 特罗姆瑟", 2265], ["特罗姆瑟 → 雷克雅未克", 1487], ["雷克雅未克 → 哥本哈根", 1692], ["哥本哈根 → 上海", 4376]], "car": [["挪威租车", "2.7 10:00 – 2.14 10:00 · 7天", 5488], ["冰岛租车", "2.14 – 2.19约04:00", 3600], ["油费", "挪威与冰岛全程预估", 4000]], "activities": [["塞尼亚岛｜Hesten／Segla 雪山徒步", 0], ["特罗姆瑟｜峡湾游船与海钓", 1358], ["特罗姆瑟｜驯鹿雪橇25–30分钟", 1534.2], ["特罗姆瑟｜自主越野滑雪 · 雪具租赁", 325.5], ["冰岛｜Skaftafell 蓝冰洞＋冰川徒步", 1083], ["冰岛｜Blue Lagoon 蓝湖 · Comfort", 1059.8]], "excluded": [["罗弗敦｜传统渔船冬季海钓", 900], ["冰岛｜Katla 冰洞＋超级吉普车", 1616.8], ["特罗姆瑟｜哈士奇雪橇", 2399], ["罗弗敦｜海鹰 RIB 与 Trollfjord", 560], ["特罗姆瑟｜Kvaløya 雪鞋登高徒步", 1054]]};
const money=n=>'¥'+n.toLocaleString('zh-CN',{maximumFractionDigits:0});
function budgetTotals(){const sum=xs=>xs.reduce((a,x)=>a+x.at(-1),0),catalog=experiences.filter(x=>!x.excluded),flights=sum(budget.flights),car=sum(budget.car),activities=sum(budget.activities.filter((x,i)=>!catalog[i]?.budgetAlternative)),alternativeActivities=activities+budget.activities.reduce((delta,x,i)=>{const item=catalog[i];if(!item?.budgetAlternative)return delta;const primary=catalog.find(e=>e.choiceGroup===item.choiceGroup&&!e.budgetAlternative);return delta+x.at(-1)-(primary?.price||0);},0),stay=lodgings.length?lodgings.reduce((sum,s)=>sum+stayBudget(s),0):budget.nights*budget.nightly,base=budget.visa+flights+car/budget.people+stay;return {flights,car,activities,alternativeActivities,stay,base,perPerson:base+activities,alternativePerPerson:base+alternativeActivities,total:(base+activities)*budget.people};}
function renderBudget(){const t=budgetTotals(),rows=(xs,shared=false,projects=false)=>xs.map((x,i)=>({x,i})).sort((a,b)=>{if(!projects)return a.i-b.i;const catalog=experiences.filter(item=>!!item.excluded===(projects==='excluded'));const rank=i=>{const item=catalog[i];return (item?.day??999)*10+(item?.id==='independent-ski-rental'?0:1);};return rank(a.i)-rank(b.i)||a.i-b.i;}).map(({x,i})=>`${projects?`<a class="budget-row budget-project" href="#experience/${experiences.filter(item=>!!item.excluded===(projects==='excluded'))[i].id}">`:'<div class="budget-row">'}<div><strong>${projects&&projects!=='excluded'?(()=>{const item=experiences.filter(item=>!item.excluded)[i],day=days.find(d=>d.num===item?.day),match=day?.date.match(/(\d+)月(\d+)日/);return match?`${match[1]}.${match[2]} `:'';})():''}${esc(x[0])}</strong>${x.length===3?`<small>${esc(x[1])}</small>`:''}${projects&&projects!=='excluded'?(()=>{const item=experiences.filter(item=>!item.excluded)[i];return item?.id==='independent-ski-rental'?'<small>现场租赁</small>':'';})():''}</div><span>${money(x.at(-1))}${shared?'<small>2人合计</small>':'<small>／人</small>'}</span>${projects?'</a>':'</div>'}`).join(''),section=(title,content,total,label='／人')=>`<section class="budget-section"><header><h2>${title}</h2></header>${content}<div class="budget-subtotal"><span>小计</span><strong>${typeof total==='string'?total:money(total)}<small>${label}</small></strong></div></section>`;$('#main').innerHTML=`<div class="page-wrap budget-page"><header class="budget-heading"><h1>旅行预算单</h1></header><section class="budget-summary"><div><span>每人预计</span><strong>${money(t.perPerson)}</strong></div></section>${section('签证',rows([['挪威签证',budget.visa]]),budget.visa)}${section('机票',rows(budget.flights),t.flights)}${section('住宿',stayBudgetRows(),t.stay)}${section('租车与油费',carBudgetRows(),t.car,'2人合计')}<div class="budget-base"><div class="budget-base-label"><span>基础开支</span><small>签证＋机票＋住宿预算＋自驾</small></div><strong>${money(t.base)}<small>／人</small></strong></div>${section('游玩项目',rows(budget.activities,false,true),t.activities)}<details class="budget-excluded"><summary>已排除项目 · 不计入预算</summary>${rows(budget.excluded,false,'excluded')}</details></div>`;}
function route(){closeStayPhotos();const restoreState=location.hash==='#budget'&&['experience','stay','car'].includes(view.type)?budgetReturnState:null;if(view.type==='budget'&&(location.hash.startsWith('#experience/')||location.hash.startsWith('#stay/')||location.hash.startsWith('#car/'))&&budgetReturnState?.href!==location.hash)rememberBudgetPosition(location.hash);closePoint();closeMap();if(!keepNavOnRoute)closeNav();keepNavOnRoute=false;if(observer){observer.disconnect();observer=null;}maps.forEach(x=>x.map.remove());maps=[];const hash=location.hash.slice(1).split('/');if(hash[0]==='car'&&hash[1]===norwayRental.id){view={type:'car',id:norwayRental.id};currentCountry='norway';renderCar(norwayRental);document.title='挪威租车 · 沃尔沃 EX30 — 北欧旅行计划 V2';}else if(hash[0]==='stay'&&lodgings.some(x=>x.id===hash[1])){const item=lodgings.find(x=>x.id===hash[1]);view={type:'stay',id:item.id,option:0};currentCountry=item.country;renderStay(item);document.title=item.options[0].name+' · 住宿 — 北欧旅行计划 V2';}else if(hash[0]==='experience'&&experiences.some(x=>x.id===hash[1])){const item=experiences.find(x=>x.id===hash[1]);view={type:'experience',id:item.id};currentCountry=item.country;renderExperience(item);document.title=item.title+' — 北欧旅行计划 V2';}else if(hash[0]==='packing'){view={type:'packing'};window.renderPacking();document.title='行李清单 — 北欧旅行计划';}else if(hash[0]==='budget'){view={type:'budget'};renderBudget();document.title='预算清单 — 北欧旅行计划 V2';}else if(hash[0]==='day'&&days.some(d=>d.num===Number(hash[1]))){const d=days.find(d=>d.num===Number(hash[1]));view={type:'day',num:d.num};currentCountry=countryOf(d).id;renderDay(d,countryOf(d));document.title=`DAY ${d.num} · ${d.title} — 北欧旅行计划 V2`;}else if(hash[0]==='country'&&countries.some(c=>c.id===hash[1])){view={type:'country',id:hash[1]};currentCountry=hash[1];renderCountry(countryById(hash[1]));document.title=countryById(hash[1]).name+' · 路线总览 — 北欧旅行计划 V2';}else{view={type:'home'};renderHome();document.title='北欧旅行计划 V2 · 2027';}sideRender();window.syncVersionUI?.();if(restoreState)restoreBudgetPosition(restoreState);else window.scrollTo({top:0,behavior:'instant'});}
const icons={airport:'✈️',transport:'🚏',nature:'🏔️',sight:'📍',shopping:'🛍️',food:'🍽️',spa:'♨️',stay:'🏡',optional:'◌'};
function createMap(id,pts,title,modal=false,routeCountryId=null,dayNumber=null){const el=document.getElementById(id);if(!el)return;if(!window.L){el.innerHTML='<div class="empty-map">地图资源暂时无法加载，请稍后重试。</div>';return;}const map=L.map(el,{scrollWheelZoom:modal,zoomControl:false,attributionControl:true,minZoom:2,maxZoom:18});map.zoomControl=L.control.zoom({zoomInText:'<svg class="map-control-icon" viewBox="0 0 24 24" width="20" height="20" aria-hidden="true" focusable="false"><path d="M12 5v14M5 12h14"/></svg>',zoomOutText:'<svg class="map-control-icon" viewBox="0 0 24 24" width="20" height="20" aria-hidden="true" focusable="false"><path d="M5 12h14"/></svg>',zoomInTitle:'放大地图',zoomOutTitle:'缩小地图'}).addTo(map);const tile=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Dark_Gray_Base/MapServer/tile/{z}/{y}/{x}',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> · Esri, HERE, Garmin',maxNativeZoom:16,maxZoom:19});tile.addTo(map);let failures=0;tile.on('tileerror',()=>{if(++failures===5&&!el.querySelector('.map-error')){const n=document.createElement('div');n.className='map-error';n.textContent='底图加载较慢，点位仍可点击；也可展开查看列表。';el.appendChild(n);}});const numberedDay=Number(dayNumber)||null,coreMap=pts.some(p=>p.core);const group=L.markerClusterGroup&&!coreMap&&!numberedDay?L.markerClusterGroup({showCoverageOnHover:false,maxClusterRadius:42,disableClusteringAtZoom:13,spiderfyOnMaxZoom:true,iconCreateFunction:cluster=>L.divIcon({className:'map-cluster',html:'<span>'+cluster.getChildCount()+'</span>',iconSize:[34,34]})}).addTo(map):map;const baseLines=[];const markers=[];pts.forEach((p,index)=>{const marker=L.marker([p.coord[1],p.coord[0]],{icon:numberedDay?dayPointIcon(p,index+1):L.divIcon({className:p.core?'map-city-marker':'map-marker '+p.kind,html:p.core?'':icons[p.kind]||'📍',iconSize:p.core?[11,11]:[29,29],iconAnchor:p.core?[5,5]:[14,14]}),title:p.core?p.name+' '+dayRanges(p.days):p.name,keyboard:true}).addTo(group);marker.bindTooltip(cityMapLabel(p),{className:p.core?'map-city-label':'map-marker-label',permanent:!!p.core,direction:p.direction||'top',offset:p.offset||[0,-15]});marker.on('click',()=>openPoint(p));markers.push({p,marker});});if(pts.length){map.fitBounds(pts.map(p=>[p.coord[1],p.coord[0]]),{padding:[42,55],maxZoom:13});}else map.setView([63,15],3);if(numberedDay){const placed=[];markers.forEach(({p,marker},index)=>marker.setIcon(dayPointIcon(p,index+1,routePinAnchor(map.project([p.coord[1],p.coord[0]]),placed))));}if(coreMap){const routeIds=['core-p1','core-p24','core-p30','core-p40','core-p24','core-p52','core-p58','core-p65','core-p73'];const route=routeIds.map(id=>pts.find(p=>p.id===id)).filter(Boolean).map(p=>[p.coord[1],p.coord[0]]);baseLines.push(L.polyline(route,{color:'#a4bdb1',weight:2,opacity:.7,dashArray:'4 8',interactive:false}).addTo(map));}if(!coreMap&&pts.length>1&&pts.length<35){const coords=pts.filter(p=>p.kind!=='optional').map(p=>[p.coord[1],p.coord[0]]);baseLines.push(L.polyline(coords,{color:'#94b4ba',weight:2,opacity:.6,dashArray:'4 8',interactive:false}).addTo(map));}map.zoomControl.setPosition('bottomleft');const obj={id,map,pts,title,markers,group,baseLines,dayNumber:numberedDay,activePoints:pts,routeVisible:false,routeDay:'all',routeCountry:routeCountryId?countryById(routeCountryId):null};if(obj.routeCountry)addCountryRouteControl(obj);if(modal)expanded=obj;else maps.push(obj);setTimeout(()=>map.invalidateSize(),100);return obj;}
// Ordered main stops, not turn-by-turn road geometry. Alternatives remain on the POI map.
const countryDayStops={"1": ["p0", "p1", "p13", "p2", "p3", "p5", "p6", "p8"], "2": ["p0", "p20", "p21", "p24", "p23", "p22", "p-fjellheisen"], "3": ["p-charlottenlund", "p-ski", "p-reindeer", "p24", "p-pust"], "4": ["p24", "p28", "p29", "p30"], "5": ["p30", "p-hesten", "p30"], "6": ["p30", "p31", "p32", "p33", "p38", "p39", "p40", "p-fredvang"], "7": ["p-fredvang", "p43", "p47", "p44", "p40"], "8": ["p40", "p42", "p-kabelvag", "p39", "p20"], "9": ["p51", "p71", "p52"], "10": ["p52", "p55", "p56", "p58"], "11": ["p58", "p59", "p63", "p65", "p-reystays"], "12": ["p-reystays", "p65", "p66", "p68", "p69", "p-reystays"], "13": ["p-reystays", "p-vestrahorn", "p70", "p51"], "14": ["p72", "p75", "p73", "p74", "p-frederik", "p-frama"], "15": ["p77", "p78", "p-illums", "p-diamond", "p72"], "16": []};
const transferLegs=new Set(['p0:p15','p28:p29']);
function countryRoutes(c){return c.days.map(day=>({day,stops:(countryDayStops[day.num]||[]).map(id=>points.find(p=>p.id===id&&p.countryId===c.id&&p.days.includes(day.num))).filter(p=>p?.coord)})).filter(r=>r.stops.length);}
function dayPointIcon(point,number,anchor=[24,14]){return L.divIcon({className:'route-stop route-stop-detailed day-numbered-stop',html:`<span class="route-stop-number">${number}</span><span class="route-stop-emoji" aria-hidden="true">${routePlaceEmoji(point)}</span>`,iconSize:[48,28],iconAnchor:anchor});}
function syncRoutePoints(obj,shown){obj.activePoints=shown;const container=obj.map.getContainer?.(),banner=container?.parentElement?.querySelector('.map-banner-meta>span:first-child');if(banner)banner.textContent=`${shown.length} 个行程点位 · 点击标记探索`;if(obj===expanded){expandedPoints=shown;renderPointList($('#point-search')?.value||'');}}
function updateRouteControl(obj){if(!obj.routeUI)return;const ui=obj.routeUI;ui.querySelector('[data-route-action="toggle"]').setAttribute('aria-pressed',String(obj.routeVisible));ui.querySelector('[data-route-action="toggle"]').hidden=obj.routeVisible;ui.querySelector('.route-picker').hidden=!obj.routeVisible;ui.querySelectorAll('[data-route-day]').forEach(button=>{const selected=button.dataset.routeDay===String(obj.routeDay);button.classList.toggle('active',selected);button.setAttribute('aria-pressed',String(selected));});}
function addCountryRouteControl(obj){const available=countryRoutes(obj.routeCountry);if(!available.length)return;const control=L.control({position:'bottomright'});control.onAdd=()=>{const ui=document.createElement('div');ui.className='country-route-control';ui.setAttribute('role','group');ui.setAttribute('aria-label','按天查看行程路线');ui.innerHTML=`<button class="route-toggle" data-route-action="toggle" aria-pressed="false"><span class="route-toggle-label">查看行程路线</span></button><div class="route-picker" hidden><div class="route-day-tabs" aria-label="选择日期"><button data-route-day="all" aria-pressed="true" class="active">全部</button>${available.map(r=>`<button data-route-day="${r.day.num}" aria-pressed="false">Day ${r.day.num}</button>`).join('')}</div></div>`;ui.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.routeAction==='toggle')showCountryRoutes(obj,!obj.routeVisible);else if(button.dataset.routeDay){obj.routeDay=button.dataset.routeDay;showCountryRoutes(obj,true);}});L.DomEvent.disableClickPropagation(ui);L.DomEvent.disableScrollPropagation(ui);obj.routeUI=ui;return ui;};control.addTo(obj.map);obj.routeControl=control;}
function animateRouteLine(line,delay){const path=line.getElement?.();if(!path||typeof path.animate!=='function'||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const length=path.getTotalLength();if(!length)return;path.animate([{strokeDasharray:`${length} ${length}`,strokeDashoffset:length},{strokeDasharray:`${length} ${length}`,strokeDashoffset:0}],{duration:1000,delay,fill:'backwards',easing:'ease-out'});}
function routeDistance(a,b){const rad=Math.PI/180,dlat=(b.coord[1]-a.coord[1])*rad,dlon=(b.coord[0]-a.coord[0])*rad,x=Math.sin(dlat/2)**2+Math.cos(a.coord[1]*rad)*Math.cos(b.coord[1]*rad)*Math.sin(dlon/2)**2;return 6371*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x));}
function routeLegMode(day,from,to){if(from.id==='p28'&&to.id==='p29')return 'ferry';if([1,14,15].includes(day)&&routeDistance(from,to)>2)return 'rail';return day>=2&&day<=13&&routeDistance(from,to)>2?'drive':'walk';}
function routePlaceEmoji(p){return ({p5:'🛍️',p6:'🛍️',p7:'🛍️',p8:'🛍️',p10:'🍸',p11:'🥐',p12:'🛍️',p13:'📚',p14:'⛪',p18:'♨️',p19:'🎅',p22:'🏛️',p25:'🚐',p28:'⛴️',p29:'⛴️',p41:'🎣',p53:'⛪',p55:'💦',p56:'💦',p59:'🏖️',p66:'🧊',p68:'🧊',p69:'💎',p71:'♨️',p74:'🏛️',p77:'🏛️',p78:'🛍️',p79:'🖼️',p80:'🥐',p81:'🏰'})[p.id]||icons[p.kind]||'📍';}
function routePinAnchor(screen,placed){const offsets=[[0,0],[-28,-34],[28,34],[28,-34],[-28,34],[-56,0],[56,0],[0,68],[0,-68],[-56,-68],[56,68],[56,-68],[-56,68]];let chosen=offsets[0],best=Infinity;for(const offset of offsets){const x=screen.x+offset[0],y=screen.y+offset[1],overlaps=placed.filter(p=>Math.abs(p.x-x)<52&&Math.abs(p.y-y)<32).length,score=overlaps*1000+Math.hypot(...offset);if(score<best){best=score;chosen=offset;}}placed.push({x:screen.x+chosen[0],y:screen.y+chosen[1]});return [24-chosen[0],14-chosen[1]];}
function showCountryRoutes(obj,visible){const map=obj.map;if(obj.routeLayer){map.removeLayer(obj.routeLayer);obj.routeLayer=null;}obj.routeVisible=visible;if(!visible){syncRoutePoints(obj,obj.pts);if(obj.group!==map&&!map.hasLayer(obj.group))obj.group.addTo(map);else if(obj.group===map)obj.markers.forEach(({marker})=>marker.addTo(map));obj.baseLines.forEach(line=>line.addTo(map));if(obj.pts.length)map.fitBounds(obj.pts.map(p=>[p.coord[1],p.coord[0]]),{padding:[42,55],maxZoom:13});updateRouteControl(obj);return;}
if(obj.group!==map)map.removeLayer(obj.group);else obj.markers.forEach(({marker})=>map.removeLayer(marker));obj.baseLines.forEach(line=>map.removeLayer(line));const routes=countryRoutes(obj.routeCountry).filter(r=>obj.routeDay==='all'||r.day.num===Number(obj.routeDay));const shown=[...new Map(routes.flatMap(r=>r.stops).map(p=>[p.id,p])).values()];syncRoutePoints(obj,shown);const coords=routes.flatMap(r=>r.stops.map(p=>[p.coord[1],p.coord[0]]));obj.routeLayer=L.layerGroup().addTo(map);if(!coords.length){updateRouteControl(obj);return;}map.fitBounds(coords,{paddingTopLeft:[45,70],paddingBottomRight:[45,95],maxZoom:14,animate:false});const palette={finland:['#a4d4b9','#d4e8aa','#81c8b5'],norway:['#9bcbe7','#d5dfb0','#91d8d7','#b5b5ec','#f0cf9f','#a8d4bd'],iceland:['#85d5db','#bcd7a5','#c7c1ee','#e4d09a','#91c6ea'],denmark:['#efb7a4','#d6c4eb','#dfd7ac','#a6cfd0']}[obj.routeCountry.id];const labels=[],placedPins=[],transportEmoji={flight:'✈️',ferry:'⛴️',drive:'🚗',rail:'🚆'};
routes.forEach(r=>{const dayIndex=obj.routeCountry.days.findIndex(d=>d.num===r.day.num),color=palette[dayIndex%palette.length],stopsByPlace=new Map();r.stops.forEach((point,i)=>{if(i){const from=r.stops[i-1],a=[from.coord[1],from.coord[0]],b=[point.coord[1],point.coord[0]],mode=routeLegMode(r.day.num,from,point),line=L.polyline([a,b],{color,weight:3,opacity:.95,dashArray:mode==='walk'?null:'7 7',lineCap:'round',interactive:false}).addTo(obj.routeLayer);animateRouteLine(line,dayIndex*160+(i-1)*100);const p1=map.project(a),p2=map.project(b),screenLength=p1.distanceTo(p2),midpoint=L.point((p1.x+p2.x)/2,(p1.y+p2.y)/2),mid=map.unproject(midpoint),crowded=coords.filter(coord=>map.project(coord).distanceTo(midpoint)<60).length>2;
if(mode!=='walk'&&screenLength>65&&!crowded)L.marker(mid,{interactive:false,keyboard:false,icon:L.divIcon({className:'route-transport',html:`<span>${transportEmoji[mode]}</span>`,iconSize:[26,26],iconAnchor:[13,13]})}).addTo(obj.routeLayer);else if(mode==='walk'&&routeDistance(from,point)<2&&screenLength>110&&!crowded){const angle=Math.atan2(p2.y-p1.y,p2.x-p1.x)*180/Math.PI;L.marker(mid,{interactive:false,keyboard:false,icon:L.divIcon({className:'route-direction',html:`<svg viewBox="0 0 20 20" width="12" height="12" style="transform:rotate(${angle}deg);color:${color}" aria-hidden="true"><path d="M4 3l12 7-12 7 3-7Z"/></svg>`,iconSize:[12,12],iconAnchor:[6,6]})}).addTo(obj.routeLayer);}}
const existing=stopsByPlace.get(point.id);if(existing)existing.numbers.push(i+1);else stopsByPlace.set(point.id,{point,numbers:[i+1]});});
for(const {point,numbers}of stopsByPlace.values())L.marker([point.coord[1],point.coord[0]],{title:obj.routeDay==='all'?`Day ${r.day.num} · ${point.name}`:point.name,icon:L.divIcon({className:'route-stop route-stop-detailed',html:`<span class="route-stop-number">${numbers.join('/')}</span><span class="route-stop-emoji" aria-hidden="true">${routePlaceEmoji(point)}</span>`,iconSize:[48,28],iconAnchor:routePinAnchor(map.project([point.coord[1],point.coord[0]]),placedPins)})}).bindTooltip(obj.routeDay==='all'?`Day ${r.day.num} · ${esc(point.name)}`:esc(point.name),{className:'map-marker-label',direction:'top',offset:[0,-15]}).on('click',()=>openPoint(point)).addTo(obj.routeLayer);
const first=r.stops[0],location=[first.coord[1],first.coord[0]],screen=map.project(location),near=labels.find(label=>map.project(label.location).distanceTo(screen)<40);if(near)near.days.push(r.day.num);else labels.push({location,days:[r.day.num],color});});
labels.forEach(label=>L.marker(label.location,{title:label.days.map(n=>'Day '+n).join(' · '),zIndexOffset:1200,icon:L.divIcon({className:'route-day-marker',html:`<span style="border-color:${label.color}">${label.days.map(n=>'Day '+n).join(' · ')}</span>`,iconSize:[120,28],iconAnchor:[60,42]})}).on('click',()=>{obj.routeDay=String(label.days[0]);showCountryRoutes(obj,true);}).addTo(obj.routeLayer));updateRouteControl(obj);}

function openMap(id){const origin=maps.find(x=>x.id===id);if(!origin)return;lastFocus=document.activeElement;expandedPoints=origin.activePoints||origin.pts;$('#map-modal').hidden=false;$('#map-modal-title').textContent=origin.title;$('#map-list').classList.toggle('closed',innerWidth<=860);$('#points-toggle').setAttribute('aria-expanded',String(innerWidth>860));$('#point-search').value='';document.body.style.overflow='hidden';const expandedMap=createMap('expanded-map',origin.pts,origin.title,true,origin.routeCountry?.id,origin.dayNumber);if(origin.routeVisible){expandedMap.routeDay=origin.routeDay;showCountryRoutes(expandedMap,true);}renderPointList();$('#map-close').focus();}
function closeMap(){if($('#map-modal').hidden)return;if(expanded){expanded.map.remove();expanded=null;}$('#map-modal').hidden=true;document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus();}
function renderPointList(query=''){const found=expandedPoints.filter(p=>(p.name+' '+p.query).toLowerCase().includes(query.toLowerCase()));$('#point-count').textContent=`${found.length} 个`;$('#point-items').innerHTML=found.map(p=>`<button class="point-item" data-point="${p.id}"><img src="${p.image}" alt="${esc(p.imageLabel)}" loading="lazy"><span><strong>${esc(p.name)}</strong><small>${esc(p.kind==='optional'?'备选／冬季有条件开放':p.kind==='airport'?'机场':p.kind==='transport'?'交通与集合点':p.kind==='stay'?'住宿区域':'行程点位')} · DAY ${p.days.map(n=>String(n).padStart(2,'0')).join(' / ')}</small><small>Google 评分未接入 · 查看详情 ↗</small></span></button>`).join('')||'<p style="padding:24px">没有找到匹配的点位</p>';}
function openPoint(p){lastFocus=document.activeElement;$('#point-scrim').hidden=false;$('#point-sheet').hidden=false;const gmap='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p.query);const directions='https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(p.query);$('#point-sheet').innerHTML=`<div class="point-cover"><img src="${p.image}" alt="${esc(p.imageLabel)}"><button class="icon-button point-close" data-close-point aria-label="关闭点位详情"><svg class="point-close-icon" viewBox="0 0 24 24" width="14" height="14" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg></button></div><div class="point-body"><span class="eyebrow">${esc(p.countryName)} / ${esc(p.kind==='optional'?'OPTIONAL STOP':'ON THE ROUTE')}</span><h2>${esc(p.name)}</h2><div class="rating">☆ Google 评分未接入 <a href="${gmap}" target="_blank" rel="noopener noreferrer">查看实时评分 ↗</a></div><div class="point-days">${p.days.map(n=>`<a href="#day/${n}" data-point-day>DAY ${String(n).padStart(2,'0')}</a>`).join('')}</div><p>${esc(p.description||'此地点出现在原行程中。具体停留安排与注意事项请查看对应日期的完整行程。')}</p>${p.cityProfile?`<div class="city-introduction"><h3>本次停留</h3><p>${esc(p.cityProfile.plan)}</p><h3>城市与区域看点</h3><ul>${p.cityProfile.highlights.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><a class="city-source" href="${esc(p.cityProfile.source)}" target="_blank" rel="noopener noreferrer">城市／区域官方介绍 ↗</a></div>`:''}${p.kind==='optional'?'<p>原行程中的顺路／备选点位，是否前往取决于道路开放、天气与当天时间。</p>':''}${p.kind==='stay'&&p.id!=='p-reystays'?'<p>此标记为住宿区域，具体信息请查看当日住宿卡片。</p>':''}<p style="font-size:11px">地图标记用于位置参考；正式导航与活动集合点以地图和预订凭证为准。</p><a class="google-button" href="${gmap}" target="_blank" rel="noopener noreferrer">在 Google Maps 中打开 ↗</a><a class="secondary-google" href="${directions}" target="_blank" rel="noopener noreferrer">使用 Google Maps 导航</a><p style="font-size:10px">图片：${esc(p.imageLabel)}${p.imageReference?'（当日行程参考图）':''}${p.imageSource?` · <a href="${esc(p.imageSource)}" target="_blank" rel="noopener noreferrer">查看来源</a>`:''}</p></div>`;document.body.style.overflow='hidden';$('#point-sheet button').focus();}
function closePoint(){if($('#point-sheet').hidden)return;$('#point-sheet').hidden=true;$('#point-scrim').hidden=true;if($('#map-modal').hidden)document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus();}
function openNav(){$('#sidebar').classList.add('open');$('#nav-scrim').hidden=false;document.body.style.overflow='hidden';$('#sidebar .home-icon').focus();}
function closeNav(){keepNavOnRoute=false;$('#sidebar').classList.remove('open');$('#nav-scrim').hidden=true;if($('#map-modal').hidden&&$('#point-sheet').hidden)document.body.style.overflow='';}
document.addEventListener('click',e=>{const project=e.target.closest('a.budget-project');const budgetBack=e.target.closest('a[href="#budget"]');if(!e.defaultPrevented&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey&&(e.button===0||e.button===undefined)&&(project&&view.type==='budget'||budgetBack&&['stay','experience','car'].includes(view.type))){const href=(project||budgetBack).getAttribute('href');if(project)rememberBudgetPosition(href);e.preventDefault();history.pushState(null,'',href);route();}const exp=e.target.closest('[data-expand]');if(exp)openMap(exp.dataset.expand);const pt=e.target.closest('[data-point]');if(pt){const p=expandedPoints.find(p=>p.id===pt.dataset.point)||points.find(p=>p.id===pt.dataset.point);if(expanded){expanded.map.flyTo([p.coord[1],p.coord[0]],Math.max(expanded.map.getZoom(),12),{duration:.5});}openPoint(p);}if(e.target.closest('[data-close-point]'))closePoint();const st=e.target.closest('[data-side-country]');if(st){setCountry(st.dataset.sideCountry);if(view.type!=='home'){const nextHash='#country/'+st.dataset.sideCountry;keepNavOnRoute=location.hash!==nextHash&&$('#sidebar').classList.contains('open');location.hash=nextHash;}else if(innerWidth>860){scrollCountry(st.dataset.sideCountry);}}const ht=e.target.closest('[data-home-country]');if(ht)scrollCountry(ht.dataset.homeCountry);if(e.target.closest('#sidebar a'))closeNav();});
function scrollCountry(id){setCountry(id);navLock=true;$('#section-'+id)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});setTimeout(()=>navLock=false,1000);}
$('#menu-open').onclick=openNav;$('#nav-scrim').onclick=closeNav;$('#map-close').onclick=closeMap;$('#point-scrim').onclick=closePoint;$('#points-toggle').onclick=()=>{$('#map-list').classList.toggle('closed');$('#points-toggle').setAttribute('aria-expanded',String(!$('#map-list').classList.contains('closed')));setTimeout(()=>expanded?.map.invalidateSize(),260);};$('#point-search').oninput=e=>renderPointList(e.target.value);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#point-sheet').hidden)closePoint();else if(!$('#map-modal').hidden)closeMap();else closeNav();}if(e.key==='Tab'){const scope=!$('#point-sheet').hidden?$('#point-sheet'):!$('#map-modal').hidden?$('#map-modal'):$('#sidebar').classList.contains('open')?$('#sidebar'):null;if(scope){const focusable=[...scope.querySelectorAll('a,button,input,[tabindex="0"]')].filter(n=>n.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}});
window.addEventListener('hashchange',route);
Promise.all([fetch('../nordic-v2/data.json?v=29').then(r=>{if(!r.ok)throw Error('data');return r.json();}),fetch('../nordic-v2/points.json?v=16').then(r=>{if(!r.ok)throw Error('points');return r.json();}),fetch('../nordic-v2/experiences.json?v=14').then(r=>{if(!r.ok)throw Error('experiences');return r.json();}),fetch('../nordic-v2/stays.json?v=10').then(r=>{if(!r.ok)throw Error('stays');return r.json();})]).then(([cs,ps,xs,hs])=>{lodgings=hs;experiences=xs;countries=cs;days=cs.flatMap(c=>c.days);points=ps;buildPlaceLinks();route();}).catch(()=>{$('#main').innerHTML='<div class="loading"><h1>行程暂时无法加载</h1><p>请检查网络后刷新页面。</p><button onclick="location.reload()">重新加载</button></div>';});

function renderExperience(item){const c=countryById(item.country),photo=item.photos[0];$('#main').innerHTML=`<div class="page-wrap experience-page" style="--theme:${c.color}"><nav class="breadcrumb"><a href="#budget">预算单</a><span>/ 游玩项目</span></nav><article class="experience-card"><div class="experience-gallery" data-experience="${item.id}" data-photo-index="0"><div class="experience-stage"><img id="experience-photo" src="${photo.src}" alt="${esc(photo.label)}" fetchpriority="high"><button class="gallery-arrow gallery-prev" data-gallery-step="-1" aria-label="上一张图片"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m14 6-6 6 6 6"/></svg></button><button class="gallery-arrow gallery-next" data-gallery-step="1" aria-label="下一张图片"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m10 6 6 6-6 6"/></svg></button><span class="gallery-count" aria-live="polite">1 / ${item.photos.length}</span></div><div class="gallery-caption" id="gallery-caption">${esc(photo.label)}</div><div class="experience-thumbnails" aria-label="选择项目图片">${item.photos.map((p,i)=>`<button data-gallery-photo="${i}" aria-label="查看图片${i+1}：${esc(p.label)}" aria-pressed="${i===0}"><img src="${p.src}" alt="" loading="lazy"></button>`).join('')}</div></div><div class="experience-content"><p class="experience-location">${esc(item.location)}${item.day?` · DAY ${String(item.day).padStart(2,'0')}`:' · 日期待安排'}</p>${item.excluded?'<p class="experience-status">已排除 · 不计入预算</p>':''}<h1>${esc(item.title)}</h1><p class="experience-intro">${esc(item.intro)}</p><div class="experience-facts"><div><small>游玩时长</small><strong>${esc(item.duration)}</strong></div><div><small>${item.excluded?'原参考价格':'每人预算'}</small><strong>${money(item.price)}<small>／人</small></strong></div></div><section><h2>项目体验</h2><ul>${item.includes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section><h2>集合与安排</h2><p>${esc(item.meeting)}</p></section><section><h2>价格说明</h2><p>${esc(item.priceNote)}</p></section><section><h2>行前准备</h2><ul>${item.notes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><div class="experience-links">${item.day?`<a href="#day/${item.day}">查看 DAY ${String(item.day).padStart(2,'0')} 行程 ↗</a>`:''}<a href="${esc(item.url)}" target="_blank" rel="noopener">${esc(item.operator)} 项目官网 ↗</a></div><p class="experience-credit">项目资料：原旅行计划与${esc(item.operator)}；图片为项目景观参考${item.imageCredit?`，补充图片来自 <a href="${esc(item.imageSource)}" target="_blank" rel="noopener">${esc(item.imageCredit)}</a>`:item.id==='blue-lagoon'?'，蓝湖地貌图片来自 <a href="https://www.visitreykjanes.is/en/moya/gallery/index/index/myndir-fra-reykjanesi/natturan/blue-lagoon-nature-3-1" target="_blank" rel="noopener">Visit Reykjanes</a>':'，补充图片来自运营方官网'}。已订项目价格按订单折算，其余为计划预算。</p></div></article><a class="experience-back" href="#budget">← 返回旅行预算单</a></div>`;}
function selectExperiencePhoto(index){const gallery=$('.experience-gallery');if(!gallery)return;const item=experiences.find(x=>x.id===gallery.dataset.experience);if(!item)return;const next=(index%item.photos.length+item.photos.length)%item.photos.length,p=item.photos[next];gallery.dataset.photoIndex=String(next);$('#experience-photo').src=p.src;$('#experience-photo').alt=p.label;$('#gallery-caption').textContent=p.label;$('.gallery-count').textContent=`${next+1} / ${item.photos.length}`;$$('[data-gallery-photo]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===next)));}
document.addEventListener('click',event=>{const thumb=event.target.closest('[data-gallery-photo]'),arrow=event.target.closest('[data-gallery-step]');if(thumb)selectExperiencePhoto(Number(thumb.dataset.galleryPhoto));if(arrow)selectExperiencePhoto(Number($('.experience-gallery').dataset.photoIndex)+Number(arrow.dataset.galleryStep));});
document.addEventListener('keydown',event=>{if(event.target.closest?.('.experience-gallery')&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();selectExperiencePhoto(Number($('.experience-gallery').dataset.photoIndex)+(event.key==='ArrowRight'?1:-1));}});

function stayForDay(day){return lodgings.find(s=>s.days.includes(day.num));}
function stayBudget(s){return Number.isFinite(s.options[0].total)?s.options[0].total/budget.people:s.nights*budget.nightly;}
function stayPrice(s,o=s.options[0]){return Number.isFinite(o.total)?money(o.total/budget.people):o===s.options[0]?money(s.nights*budget.nightly):'价格待核实';}
function stayStatus(s,o=s.options[0]){if(o.status==='车上过夜')return '按最新计划不计住宿房费';if(o.originalTotal)return '订单应付 '+o.currency+' '+o.originalTotal+' · 2人总价 '+money(o.total);return Number.isFinite(o.total)?(o.status==='对比住宿'?'文档参考 · 2人总价':'订单折算 · 2人总价')+' '+money(o.total):o===s.options[0]?'暂按 '+money(budget.nightly)+'／人／晚':'指定日期报价待核实';}
function stayPhotoSrc(p,thumbnail=false){return '../nordic-v2/'+(thumbnail&&p.thumb?p.thumb:p.src);}
function stayPhotoSet(p){return p.medium?`${stayPhotoSrc({...p,src:p.medium})} 480w, ${stayPhotoSrc({...p,src:p.mobile})} 640w, ${stayPhotoSrc(p)} ${p.width||960}w`:'';}
function stayStagePhoto(p){return `<img id="stay-photo" src="${stayPhotoSrc({...p,src:p.mobile||p.src})}" srcset="${stayPhotoSet(p)}" sizes="(max-width: 700px) 100vw, 960px" alt="${esc(p.label)}" width="${p.width||960}" height="${p.height||640}" decoding="async" fetchpriority="high">`;}

function dayThumbnail(d){return d.photos[0]?photoSrc(d.photos[0].src,160):'';}
function dayPhotos(d){return d.photos;}
function dailyStayHTML(d){const s=stayForDay(d);if(!s)return '';const o=s.options[0];return `<a class="day-lodging" href="#stay/${s.id}">${o.photos?.[0]?`<img class="stay-card-photo" src="${stayPhotoSrc(o.photos[0],true)}" alt="${esc(o.photos[0].label)}" width="120" height="90" loading="lazy" decoding="async">`:'<span class="stay-icon" aria-hidden="true">🏡</span>'}<div><small>${esc(s.dates)} · ${s.nights}晚</small><h2>入住 ${esc(o.name)}</h2><p>${esc(o.features)}</p>${o.userNote?`<p class="stay-user-note">我的备注：${esc(o.userNote)}</p>`:''}</div><span class="stay-card-price">${stayPrice(s)}<small>／人 · ${s.nights}晚</small><small>查看详情 ↗</small></span></a>`;}
const stayDateMarkers={helsinki:'⭐','tromso-fjord':'🔥',senja:'⭐',fredvang:'⭐',svolvaer:'🔥',vik:'🔥',hof:'⭐',copenhagen:'⭐'};
function stayBudgetRows(){return lodgings.map(s=>{const o=s.options[0],room=(o.roomLayout||'房型待核实').replace('1张双人床＋2张单人床＋1张沙发床','4张床').replace('1张特大床＋1张沙发床','2张床').replace('1张双人床＋1张沙发床','2张床');return `<a class="budget-row budget-project budget-stay" href="#stay/${s.id}"><div class="stay-budget-main"><strong>${esc(s.dates)}${stayDateMarkers[s.id]||''} ${esc(s.location)}｜${esc(o.name)}</strong><small>${esc(o.budgetSummary||[o.features,o.userNote].filter(Boolean).join('；'))}</small></div><span class="stay-budget-price">${stayPrice(s)}<small>/人/${s.nights}晚</small></span><div class="stay-budget-meta"><small>${esc(room)}</small><small class="stay-budget-cancellation">${esc(o.cancellation||'取消政策以所选报价为准')}</small></div></a>`;}).join('');}
function renderStay(s){const o=s.options[0],c=countryById(s.country);view.option=0;const photos=o.photos||[];$('#main').innerHTML=`<div class="page-wrap stay-page" style="--theme:${c.color}"><nav class="breadcrumb"><a href="#budget">预算单</a><span>/ 住宿详情</span></nav><article class="experience-card stay-detail"><div class="stay-panel">${photos.length?`<div class="stay-gallery" data-stay="${s.id}" data-option="0" data-photo-index="0"><div class="experience-stage">${stayStagePhoto(photos[0])}${photos.length>1?'<button class="gallery-arrow gallery-prev" data-stay-step="-1" aria-label="上一张住宿图片"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m14 6-6 6 6 6"/></svg></button><button class="gallery-arrow gallery-next" data-stay-step="1" aria-label="下一张住宿图片"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m10 6 6 6-6 6"/></svg></button>':''}<button class="stay-browse-all" data-stay-browse="${s.id}">全部浏览 · ${photos.length}张</button><span class="gallery-count">1 / ${photos.length}</span></div><div class="gallery-caption" id="stay-caption">${esc(photos[0].caption||photos[0].label)}</div>${photos.length>1?`<div class="experience-thumbnails" aria-label="选择住宿图片">${photos.map((p,i)=>`<button data-stay-photo="${i}" aria-label="查看住宿图片${i+1}：${esc(p.caption||p.label)}" aria-pressed="${i===0}"><img src="${stayPhotoSrc(p,true)}" alt="" loading="lazy" decoding="async"></button>`).join('')}</div>`:''}</div>`:'<div class="stay-photo-empty">房源照片待补充</div>'}<div class="experience-content"><p class="experience-location">${esc(s.dates)} · ${esc(s.location)} · ${s.nights}晚</p><h1>${esc(o.name)}</h1><p class="stay-feature">${esc(o.features)}</p><p class="experience-intro">${esc(o.description)}</p>${o.userNote?`<section class="stay-personal-notes"><h2>我的备注</h2><p>${esc(o.userNote)}</p></section>`:''}<div class="experience-facts"><div><small>每人住宿合计</small><strong>${stayPrice(s,o)}</strong></div><div><small>入住／退房</small><strong>${esc(s.dates)}</strong></div></div><section><h2>房型与取消</h2><p>${esc(o.roomLayout||'房型待核实')}</p><p>${esc(o.cancellation||'取消政策以所选报价为准')}</p></section><section><h2>价格</h2><p>${esc(stayStatus(s,o))}${!Number.isFinite(o.total)?'；获得成交价后替换当前预算。':'。'}</p></section>${o.notes.length?`<section><h2>入住与路线</h2><ul>${o.notes.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></section>`:''}<div class="experience-links">${s.days.map(n=>`<a href="#day/${n}">查看 D${n} 行程 ↗</a>`).join('')}${o.url?`<a href="${esc(o.url)}" target="_blank" rel="noopener">查看公开房源 ↗</a>`:''}</div>${photos.length?`<p class="experience-credit">图片：对应房源公开页面${o.imageCredit?`，补充浴室图来自 <a href="${esc(o.imageSource)}" target="_blank" rel="noopener">${esc(o.imageCredit)}</a>`:''}；具体房型以订单为准。</p>`:''}</div></div></article><a class="experience-back" href="#budget">← 返回旅行预算单</a></div>`;}
function selectStayPhoto(index){const gallery=$('.stay-gallery');if(!gallery)return;const s=lodgings.find(x=>x.id===gallery.dataset.stay),o=s?.options[Number(gallery.dataset.option)];if(!o?.photos.length)return;const next=(index%o.photos.length+o.photos.length)%o.photos.length,p=o.photos[next];gallery.dataset.photoIndex=String(next);const img=$('#stay-photo');img.srcset=stayPhotoSet(p);img.src=stayPhotoSrc({...p,src:p.mobile||p.src});$('#stay-photo').alt=p.label;$('#stay-caption').textContent=p.caption||p.label;gallery.querySelector('.gallery-count').textContent=`${next+1} / ${o.photos.length}`;$$('[data-stay-photo]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===next)));}
document.addEventListener('click',event=>{const photo=event.target.closest('[data-stay-photo]'),step=event.target.closest('[data-stay-step]');if(photo)selectStayPhoto(Number(photo.dataset.stayPhoto));if(step)selectStayPhoto(Number($('.stay-gallery').dataset.photoIndex)+Number(step.dataset.stayStep));});
document.addEventListener('keydown',event=>{if(event.target.closest?.('.stay-gallery')&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();selectStayPhoto(Number($('.stay-gallery').dataset.photoIndex)+(event.key==='ArrowRight'?1:-1));}});

let stayPhotosFocus=null;
function closeStayPhotos(){const dialog=document.getElementById('stay-all-photos');if(!dialog)return;dialog.close();dialog.remove();document.body.classList.remove('stay-photos-open');stayPhotosFocus?.focus({preventScroll:true});stayPhotosFocus=null;}
function openStayPhotos(id){const stay=lodgings.find(s=>s.id===id);if(!stay)return;closeStayPhotos();stayPhotosFocus=document.activeElement;const photos=stay.options[0].photos,columns=[[],[]],heights=[0,0];photos.forEach((p,i)=>{const col=heights[0]<=heights[1]?0:1;columns[col].push({p,i});heights[col]+=(p.height||640)/(p.width||960)+.18;});const dialog=document.createElement('dialog');dialog.id='stay-all-photos';dialog.className='stay-all-photos';dialog.setAttribute('aria-label',stay.options[0].name+' · 全部照片');dialog.innerHTML=`<header class="stay-photos-header"><div><h2>${esc(stay.options[0].name)}</h2><span>全部照片 · ${photos.length}张</span></div><button class="stay-photos-close" aria-label="关闭全部照片"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></header><div class="stay-photo-masonry">${columns.map(column=>`<div class="stay-photo-column">${column.map(({p,i})=>`<button class="stay-photo-tile" data-stay-full-photo="${i}" aria-label="查看第${i+1}张：${esc(p.caption||p.label)}"><img src="${stayPhotoSrc({...p,src:p.medium||p.src})}" srcset="${stayPhotoSet(p)}" sizes="(max-width:700px) 48vw, 440px" width="${p.width||960}" height="${p.height||640}" alt="${esc(p.caption||p.label)}" loading="${i<2?'eager':'lazy'}" decoding="async"><span>${esc(p.caption||p.label)}</span></button>`).join('')}</div>`).join('')}</div>`;document.body.append(dialog);document.body.classList.add('stay-photos-open');dialog.addEventListener('cancel',event=>{event.preventDefault();closeStayPhotos();});dialog.addEventListener('click',event=>{if(event.target.closest('.stay-photos-close')||event.target===dialog)closeStayPhotos();const tile=event.target.closest('[data-stay-full-photo]');if(tile){const index=Number(tile.dataset.stayFullPhoto);closeStayPhotos();selectStayPhoto(index);$('.stay-gallery')?.scrollIntoView({block:'start',behavior:'smooth'});}});dialog.showModal();}
document.addEventListener('click',event=>{const button=event.target.closest('[data-stay-browse]');if(button)openStayPhotos(button.dataset.stayBrowse);});


const norwayRental={id:'norway',title:'挪威租车 · 沃尔沃 EX30',model:'沃尔沃 EX30 或同组车型',category:'紧凑型 SUV · IGBE',supplier:'Keddy by Europcar（由 Europcar 提供服务）',features:['自动挡','5座','4门','四驱','纯电动'],total:5488,pickup:'2027.2.7 10:00',dropoff:'2027.2.14 10:00',duration:'7天',station:'特罗姆瑟机场店（TOS）· 机场外',address:'SJOLUNDVEIEN 1, 9016, TROMSO, NORWAY',phone:'+47 2222 2209',hours:'10:00–18:00（以门店安排为准）',photo:'../nordic-v2/assets/cars/volvo-ex30.png'};
function carBudgetRows(){return budget.car.map((row,i)=>{const linked=i===0;return `${linked?'<a class="budget-row budget-project" href="#car/norway">':'<div class="budget-row">'}<div><strong>${esc(row[0])}</strong><small>${esc(row[1])}</small>${linked?'<small>沃尔沃 EX30 或同组 · 四驱纯电 SUV</small>':''}</div><span>${money(row[2])}<small>2人合计</small></span>${linked?'</a>':'</div>'}`;}).join('');}
function renderCar(car){const c=countryById('norway');$('#main').innerHTML=`<div class="page-wrap experience-page car-page" style="--theme:${c.color}"><nav class="breadcrumb"><a href="#budget">预算单</a><span>/ 租车详情</span></nav><article class="experience-card"><div class="car-gallery"><div class="experience-stage car-stage"><img src="${esc(car.photo)}" alt="沃尔沃 EX30 车型参考图" width="450" height="300" fetchpriority="high"></div><div class="gallery-caption">沃尔沃 EX30 · 车型参考，取车以实际同组车辆为准</div></div><div class="experience-content"><p class="experience-location">挪威 · 特罗姆瑟 · ${esc(car.duration)}</p><h1>${esc(car.title)}</h1><p class="stay-feature">${car.features.map(esc).join(' · ')}</p><p class="experience-intro">${esc(car.category)}，预订车型为${esc(car.model)}。租车公司为${esc(car.supplier)}，用于特罗姆瑟、塞尼亚与罗弗敦自驾。</p><div class="experience-facts"><div><small>租车订单合计 · 2人</small><strong>${money(car.total)}</strong></div><div><small>每人均摊 · ${esc(car.duration)}</small><strong>${money(car.total/budget.people)}</strong></div><div><small>取车时间</small><strong>${esc(car.pickup)}</strong></div><div><small>订单还车时间</small><strong>${esc(car.dropoff)}</strong></div></div><section><h2>车辆与配置</h2><ul><li>${esc(car.model)} · ${esc(car.category)}</li><li>${car.features.map(esc).join(' · ')}</li><li>预订的是车型组，车辆品牌、颜色及具体配置以取车时门店安排为准。</li></ul></section><section><h2>取还车安排</h2><p>${esc(car.station)}</p><p>${esc(car.address)}</p><p>门店电话：${esc(car.phone)}<br>凭证营业时间：${esc(car.hours)}</p><ul><li>取车：2月7日10:00。抵达后致电门店，确认机场外取车位置与接驳安排。</li><li>还车：确认单为2月14日10:00，同一门店；实际还车位置与营业时间外流程须提前向门店确认。</li></ul></section><section class="car-schedule-note"><h2>还车时间与航班衔接</h2><p>行程航班为2月14日07:50起飞，订单10:00还车晚于航班。请提前确认清晨还车、钥匙投递及返回航站楼的安排；此处保留订单原时间，提前还车安排尚待门店确认。</p></section><section><h2>价格与包含项目</h2><p>订单总价${money(car.total)}，已全额支付；提车单显示到店支付 NOK 0。按2人均摊，每人${money(car.total/budget.people)}。</p><ul><li>车辆租金、税费与无限里程。</li><li>车行基础保障：碰撞险、盗窃险及第三者责任险；碰撞与盗窃起赔额均为 NOK 17,500，第三者责任险详见门店合同。</li><li>租租车超级补充全险：列有玻璃、轮胎、底盘、道路救援费用及碰撞盗窃起赔额保障，由国内保险公司承保。</li><li>超级全车驾乘险：列有车内人员意外及财物损失保障，具体范围和除外责任以保险条款为准。</li><li>补充保险如出险需先行垫付，用车结束后联系租租车协助理赔。</li></ul></section><section><h2>取车前准备</h2><ul><li>按订单要求携带驾照原件及认可的翻译／认证文件、护照和主驾驶人信用卡，准备提车凭证。</li><li>核对冬胎、车况、充电操作与还车电量要求；拍照留存交车状态。</li><li>纯电车型需结合冬季路况规划充电停留，实际车辆和补能规则以门店交车说明为准。</li></ul></section><p class="experience-credit">车型图片：租租车确认邮件；租赁信息：最新租车确认单与提车凭证。时间均为当地时间。</p></div></article><a class="experience-back" href="#budget">← 返回旅行预算单</a></div>`;}
